const payload = $json.body || $json;
const now = new Date().toISOString();
const sensitive = ['email','phone','ssn','password','ccn','card_number','social_security'];
const sanitize = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;
  const copy = Array.isArray(obj) ? obj.slice() : { ...obj };
  for (const key of Object.keys(copy)) {
    const lower = key.toLowerCase();
    if (sensitive.includes(lower) || lower.includes('secret') || lower.includes('token') || lower.includes('password')) {
      copy[key] = 'REDACTED';
      continue;
    }
    if (typeof copy[key] === 'object') copy[key] = sanitize(copy[key]);
  }
  return copy;
};

const eventPayload = sanitize(payload.event || payload);

return [{
  json: {
    workflow_execution_id: (eventPayload.workflow_execution_id || $execution.id).toString(),
    session_id: (eventPayload.session_id || '').toString(),
    customer_id: (eventPayload.customer_id || '').toString(),
    channel: (eventPayload.channel || 'web').toString(),
    intent: (eventPayload.intent || 'UNKNOWN').toString(),
    selected_tool: (eventPayload.selected_tool || 'NONE').toString(),
    duration: Number(eventPayload.duration_ms || 0),
    success: eventPayload.success !== false,
    error_type: eventPayload.error_type || '',
    timestamp: now,
    event_type: (eventPayload.event_type || 'MESSAGE_RECEIVED').toString(),
    extra: eventPayload
  }
}];

const p = $json;
return [{
  json: {
    logged: true,
    storage: 'external',
    workflow_execution_id: p.workflow_execution_id,
    session_id: p.session_id,
    customer_id: p.customer_id,
    channel: p.channel,
    intent: p.intent,
    selected_tool: p.selected_tool,
    duration: p.duration,
    success: p.success,
    error_type: p.error_type || '',
    timestamp: p.timestamp,
    event_type: p.event_type
  }
}];

